const CC_RU_EXTRA_T3={"aq":"Антарктида","bq":"Бонэйр, Синт-Эстатиус и Саба","bw":"Ботсвана","dj":"Джибути","fo":"Фарерские острова","mc":"Монако","mg":"Мадагаскар","mp":"Северные Марианские Острова","re":"Реюньон","sk":"Словакия","st":"Сан-Томе и Принсипи","vi":"Виргинские острова (США)"};
const CC_EN_EXTRA_T3={"aq":"Antarctica","bq":"Caribbean Netherlands","bw":"Botswana","dj":"Djibouti","fo":"Faroe Islands","mc":"Monaco","mg":"Madagascar","mp":"Northern Mariana Islands","re":"Réunion","sk":"Slovakia","st":"São Tomé and Príncipe","vi":"U.S. Virgin Islands"};
const T3_STAGE_DATE={"P":"июл 2025","L":"июл 2025","G":"авг 2025"};

// The 2025 field brings seventeen countries no earlier set carried, and Majors
// 2 and 3 bring fourteen more between them. Applied the same way the Major 2
// block applies its own, and the flag lookup is rebuilt afterwards because it
// is keyed by country name, not by code.
//
// Filled into blanks rather than assigned over. The three 2025 sets overlap
// heavily in countries, so a plain assign would let whichever set loads last
// restate a name an earlier one already gave -- invisible while the spellings
// agree, and a silent change to a shipped card's flag label the day they do
// not. Proven inert for Major 1: none of its seventeen codes was already in
// CC_RU, so blanks-only and assign-over do the same thing there.
[[CC_RU_EXTRA_T1, CC_EN_EXTRA_T1],
 [CC_RU_EXTRA_T2, CC_EN_EXTRA_T2],
 [CC_RU_EXTRA_T3, CC_EN_EXTRA_T3]].forEach(pair=>{
  Object.keys(pair[0]).forEach(c=>{ if(!CC_RU[c]) CC_RU[c]=pair[0][c]; });
  Object.keys(pair[1]).forEach(c=>{ if(!CC_EN[c]) CC_EN[c]=pair[1][c]; });
});
Object.keys(CC_RU).forEach(code=>{ FLAG_CODE[CC_RU[code]]=code; });

const CARD_M1_PLAYIN_EVENT='FNCS 2026 Major 1 — Play-In Stage (Europe)';
const CARD_M1_PLAYIN_DATE='\u043c\u0430\u0440 2026';
const CARD_M1_LCQ_EVENT='FNCS 2026 Major 1 — Last Chance Qualifier (Europe)';
const CARD_M1_LCQ_DATE='\u0430\u043f\u0440 2026';
const CARD_M1_GF_EVENT='FNCS 2026 Major 1 — Grand Finals (Europe)';
const CARD_M1_GF_DATE='\u0430\u043f\u0440 2026';

// Потолок рейтинга региона — по тому, как его команды играют на международных ЛАНах:
// средний процентиль места в финале (1 — первое, 0 — последнее) на World Cup 2019 (соло и дуо),
// Invitational 2022, Глобалах в Форт-Уэрте 2024 и Лионе 2025, сжатый к 0.35 на весе 10 команд
// (у NA West и Ближнего Востока выборки малы). EU ≈ .57 и NA Central ≈ .54 — оба 96; дальше
// 96 − 30·(отставание от Европы): NA West .45 → 92, Бразилия .40 → 91, Азия .33 → 89,
// Ближний Восток .30 → 88, Океания .24 → 86. Раньше у всех, кроме EU и NAC, стояло 85.
const REGION_TOP={EU:96, NAC:96, NAW:92, BR:91, OCE:86, ASIA:89, ME:88};

// Eliminations are worth 4 points each in FNCS 2026 duos — the same multiplier
// the simulation runs on. Knowing it lets the published point total be split
// back into the two things that earned it, which is a real axis the leaderboard
// does not print directly: who scores by fragging and who scores by surviving.
const KILL_MULT=4;
// One parser for every set. 2026 rows carry two names and no elimination-points
// column, so the split has to be inferred from the multiplier above. 2025 rows
// carry three names and the column Epic actually publishes, so the split is
// read instead — which matters because its group stage marks a qualified team
// with a flat +1000, and inferring the share for those teams would hand a
// fake-high Endgame to exactly the players the format already rewarded.
// The multiplier is an argument because it is not a constant of the game: 2026
// duos pay 4, and 2025 pays 1 in the Last Chance Qualifier, 2 in the Play-In
// and 4 in the Grand Finals.
function rowEntry(r, opts){
  opts = opts || {};
  const killMult = (opts.killMult==null) ? KILL_MULT : opts.killMult;
  const at = (opts.elimPtsAt==null) ? -1 : opts.elimPtsAt;
  const matches=Math.max(r[2],1);
  const tpm=r[1]/matches;
  // Names sit at the tail of the row, after whichever numeric columns the set
  // carries, so two of them and three of them read the same way.
  const names=r.slice(at>=0 ? at+1 : 6).filter(v=>typeof v==='string');
  const elimPts = at>=0 ? r[at] : r[4]*matches*killMult;
  return {rank:r[0], pts:r[1], matches:r[2], wins:r[3], avgElims:r[4], avgPlace:r[5],
          duo:names,
          wpm:r[3]/matches, tpm,
          survival:-r[5],   // lower average placement is better, so invert it
          // Share of the points that came from placement rather than kills.
          // Clamped because a low-scoring team can out-earn its own point
          // total on eliminations alone, which would read as a negative share.
          endShare: r[1]>0 ? clamp((r[1]-elimPts)/r[1], 0, 1) : 0};
}
// The 2026 sets call through this. Same arithmetic as before, scaled top and
// bottom by the match count, so every existing card is unmoved.
function m1Entry(r){ return rowEntry(r); }
const _M1P=CARD_M1_PLAYIN_RAW.map(m1Entry);
