const CARD_M1_LCQ1_EVENT="FNCS 2026 Major 1 — Last Chance Qualifier Session 1 (Europe)";
const CARD_M1_LCQ1_DATE="20 апр 2026";
const _M1L=CARD_M1_LCQ_RAW.map(m1Entry);
const _M1L1=CARD_M1_LCQ1_RAW.map(m1Entry);
const _M1G=CARD_M1_GF_RAW.map(m1Entry);
const sortBy=(arr,f)=>arr.map(f).sort((a,b)=>a-b);

// Career volume, tallied off the same leaderboards the attributes come from.
// Every stage a player appears in adds its matches, so the count is "how much
// FNCS this person has actually played" rather than anything invented. Filled
// by mkSorts as each stage's table is built, then ranked on first use.
const _EXP=Object.create(null);
function registerExp(arr){
  arr.forEach(e=>e.duo.forEach(nm=>{
    const k=String(nm||'').toLowerCase();
    if(!k) return;
    const rec=_EXP[k] || (_EXP[k]={matches:0, stages:0});
    rec.matches += e.matches||0;
    rec.stages  += 1;
  }));
}
// A stage's percentile tables. Every stage is ranked against itself, so a card
// says "this good among the people who were in that lobby" — a 3.0 elim average
// is elite in a Grand Final and ordinary in an open qualifier.
function mkSorts(arr){
  registerExp(arr);
  return {aim:sortBy(arr,r=>r.avgElims), sur:sortBy(arr,r=>r.survival),
          clu:sortBy(arr,r=>r.wpm),      con:sortBy(arr,r=>r.tpm),
          end:sortBy(arr,r=>r.endShare)};
}
const _S={m1p:mkSorts(_M1P), m1l:mkSorts(_M1L), m1g:mkSorts(_M1G)};
_S.m1l1=mkSorts(_M1L1);

// Ranked lazily: every stage has to have registered before the distribution
// means anything, and the first card is not built until the draft opens.
let _expSorted=null;
function expPct(name){
  if(!_expSorted) _expSorted=Object.keys(_EXP).map(k=>_EXP[k].matches).sort((a,b)=>a-b);
  const rec=_EXP[String(name||'').toLowerCase()];
  return rec ? pctOf(_expSorted, rec.matches) : 0.5;
}

// Shared tail: re-centre the offsets on the base, clamp, pick a role. The
// offsets arrive as percentile deviations, so re-centring keeps the overall on
// the rating the placement earned while the shape stays the player's own.
function finishAttrs(off, base){
  const mean=ATTR_KEYS.reduce((s,k)=>s+off[k]*ATTR_W[k],0);
  const a={};
  ATTR_KEYS.forEach(k=>{ a[k]=Math.round(clamp(base+off[k]-mean, 35, 99)); });
  a.ovr=Math.round(ATTR_KEYS.reduce((s,k)=>s+a[k]*ATTR_W[k],0));
  a.bestAttr=bestPlayAttr(a);
  a.roleKey=roleFromProfile(a);
  return a;
}

// Experience is ranked against everyone in the dataset while the other five are
// ranked inside their own lobby, so its number is not on the same scale as
// theirs and it won 'highest attribute' on 39% of cards purely from that. It is
// also not a playstyle — a veteran is not automatically the caller — so the
// role and the card's headline trait come from the five columns that describe
// how the player actually scores.
// Resolved on first use: ATTR_KEYS is declared further down the file than this
// function, and a top-level filter here would run before it exists.
let ROLE_ATTRS=null;
function bestPlayAttr(a){
  if(!ROLE_ATTRS) ROLE_ATTRS=ATTR_KEYS.filter(k=>k!=='exp');
  let best=ROLE_ATTRS[0];
  ROLE_ATTRS.forEach(k=>{ if(a[k]>a[best]) best=k; });
  return best;
}
// The role is decided by the whole profile, not by the single tallest column.
// Endgame is the tallest on 42% of cards, so reading one column made 58% of the
// game callers no matter how the map was shuffled — the imbalance was in the
// data, not in the mapping. Averaging each side compares what a player is good
// at rather than which bar happens to peak.
const FRG_ATTRS=['aim','clu','con'], IGL_ATTRS=['end','sur'];
function roleFromProfile(a){
  const avg=keys=>keys.reduce((s,k)=>s+a[k],0)/keys.length;
  return avg(FRG_ATTRS) >= avg(IGL_ATTRS) ? 'roleFRG' : 'roleIGL';
}

// Every offset is a percentile of a published column, mapped to ±11 around the
// base. Aim tracks average eliminations, survival tracks average placement,
// clutch tracks Victory Royales per match, consistency tracks points per match,
// endgame tracks how much of the score came from placement instead of kills.
// Experience is the one career-wide column: it ranks the player against the
// whole dataset rather than their own lobby, so it stays the same on every card
// of that person no matter which stage the card is cut from. No RNG — two
// players with identical leaderboard lines now get identical cards, which is
// the point.
function buildM1Attrs(entry, name, sorts, base, penalty){
  const spread=p=>(p-0.5)*22;
  const off={
    aim: spread(pctOf(sorts.aim, entry.avgElims)),
    sur: spread(pctOf(sorts.sur, entry.survival)),
    clu: spread(pctOf(sorts.clu, entry.wpm)),
    con: spread(pctOf(sorts.con, entry.tpm)),
    end: spread(pctOf(sorts.end, entry.endShare)),
    exp: spread(expPct(name))
  };
  return finishAttrs(off, base-(penalty||0));
}

const m1PlayinBase = r => 96 - ((r-1)/Math.max(_M1P.length-1,1))*34;
const m1LcqLen  = () => _M1L.length + _M1L1.length;
const m1LcqBase    = r => 62 - ((r-1)/Math.max(m1LcqLen()-1,1))*14;
const m1Lcq1Base   = r => 62 - ((_M1L.length+r-1)/Math.max(m1LcqLen()-1,1))*14;
const m1GfBase     = r => 96 - ((r-1)/Math.max(_M1G.length-1,1))*26;

/* Один человек = один регион круга. Curve & Veno: NAC во всех восьми наборах, но в третьем капе Reload в EU
   плей-ине с 56/77 вместо 92-93, в драфте два Veno в одном лобби. Howly & 1Lusha держим в EU, Moneymaker & Fnajen
   в NAC Мейджоре 2.
   Правим здесь, а не в таблицах: они импорт с Tracker. Ключ: набор и регион, ИЗ которого убираем; ник
   нормализуется (полноширинный «!»). Отказ стоит в buildMajor1, buildMajor2ME, buildEwcCup.
   Совпадение ника не значит один человек (137 ников заняты дважды), страна и орг не доказательство, они лежат по
   нику без региона. Признак: одна пара в двух регионах (tools/check-card-pairs.js), одиночные ники:
   tools/check-card-dupes.js. */
/* Reet и Cooper — только Америка Центральная (4 сентября, игрок: «и cooper
   с reet есть и на NAC и на NAW»). Пара стояла в r3 NAC с 86/90 и в r4 NAW с
   76/76 (tools/check-card-pairs.js). НАК — их сцена во всех остальных наборах
   файла: оба лежат в NAC-таблицах 2025 (t1-t3), в обоих Мейджорах 2026 и в
   четырёх кубках Reload из пяти; NAW у них ровно один кубок. Снят он, а не
   таблицы: строка в ледже Tracker остаётся, карточки в NAW больше нет. */
const CARD_WRONG_REGION={
  r2: {NAW: ['bluisha cuthbert', 'Exist']},
  r3: {EU: ['Curve', 'Veno'], ME: ['Zenox', 'RinzY'], NAC: ['Xpon', 'Doxey']},
  r4: {NAW: ['Reet', 'Cooper'], NAC: ['VicterV', 'Khanada']},
  m1: {EU: ['Moneymaker', 'Fnajen'], NAC: ['f4 tibstach.', 'Jasper']},
  m2: {ME: ['Howly', '1Lusha']},
  t3: {NAC: ['fazer', 'FUT phzin 伊万尔', 'K1nG']}
};
/* Своя нормализация, а не _gcNorm: тот объявлен через const на двадцать тысяч
   строк ниже, а карточки строятся ЗДЕСЬ, при загрузке файла — обращение к нему
   отсюда падает в мёртвую зону. Правило то же: буквы и цифры, остальное прочь. */
const cardWrongNick=s=>String(s||'').toLowerCase().replace(/[^a-z0-9]/g,'');
function cardNotHere(set, reg, duo){
  const list=(CARD_WRONG_REGION[set]||{})[reg];
  if(!list) return false;
  const bad=list.map(cardWrongNick);
  return (duo||[]).some(h=>bad.indexOf(cardWrongNick(h))>=0);
}

const CARD_DUOS_M1=[];
(function buildMajor1(){
  const known=new Set();
  const add=(entry, ev, date, base, key)=>{
    // Пара, которую здесь не считают: см. CARD_WRONG_REGION.
    if(cardNotHere('m1', 'EU', entry.duo)) return;
    CARD_DUOS_M1.push({handles:entry.duo.slice()});
    entry.duo.forEach(nm=>{
      if(known.has(nm)) return;
      known.add(nm);
      const rating=Math.round(clamp(base(entry.rank), 30, 99));
      const code = M1_NAT_LIQUI[nm] || M1_NAT_TRN[nm] || M1_LCQ1_NAT[nm] || '';
      const card={
        handle:nm, nat: code ? (CC_RU[code]||null) : null,
        natSource: M1_NAT_LIQUI[nm] ? 'liquipedia' : 'tracker',
        region:'EU', event:ev, date:date, placement:entry.rank, note:'',
        tier:'cardmode', cardSet:'m1', rarity:rarityForRating(rating), rating,
        org: M1_ORG[nm] || null,
        real:{rank:entry.rank, pts:entry.pts, matches:entry.matches, wins:entry.wins,
              avgElims:entry.avgElims, avgPlace:entry.avgPlace, stage:key}
      };
      card['_m1'+key]=entry;
      pushCard(card);
    });
  };
  _M1P.forEach(e=>{ if(cardNotHere('m1', 'EU', e.duo)) return;
                    TEAMMATE_GROUPS.push(e.duo.slice()); add(e, CARD_M1_PLAYIN_EVENT, CARD_M1_PLAYIN_DATE, m1PlayinBase, 'Playin'); });
  _M1L.forEach(e=>add(e, CARD_M1_LCQ_EVENT, CARD_M1_LCQ_DATE, m1LcqBase, 'Lcq'));
  _M1L1.forEach(e=>add(e, CARD_M1_LCQ1_EVENT, CARD_M1_LCQ1_DATE, m1Lcq1Base, 'Lcq1'));
  _M1G.forEach(e=>add(e, CARD_M1_GF_EVENT, CARD_M1_GF_DATE, m1GfBase, 'Gf'));

  // Same rule as Major 2: finalists are rebuilt from the Grand Finals, everyone
  // else keeps their qualifying-stage rating minus a flat 10.
  const byName={};
  PLAYERS_BASE.filter(p=>p.cardSet==='m1').forEach(p=>{ byName[p.handle]=p; });
  const finalists=new Set();
  _M1G.forEach(entry=>{
    if(cardNotHere('m1', 'EU', entry.duo)) return;
    CARD_DUOS_M1.unshift({handles:entry.duo.slice()});
    entry.duo.forEach(nm=>{
      const p=byName[nm]; if(!p) return;
      finalists.add(nm);
      p._m1Gf=entry; p._attrs=null; p.gfEvent=CARD_M1_GF_EVENT;
      p.realGf={rank:entry.rank, pts:entry.pts, matches:entry.matches, wins:entry.wins,
                avgElims:entry.avgElims, avgPlace:entry.avgPlace};
      p.rating=Math.round(clamp(m1GfBase(entry.rank), 30, 99));
      p.rarity=rarityForRating(p.rating);
    });
  });
  Object.keys(byName).forEach(nm=>{
    if(finalists.has(nm)) return;
    const p=byName[nm];
    p.missedGf=true;
    const base = p._m1Playin ? missedGfPlayinBase(p._m1Playin.rank, _M1P.length)
               : p._m1Lcq   ? missedGfLcqBase(p._m1Lcq.rank, _M1L.length) : p.rating-NO_GF_PENALTY;
    p.rating=Math.round(clamp(base, 30, 99));
    p.rarity=rarityForRating(p.rating);
  });
})();

