const CARD_N1_LCQ1_EVENT="FNCS 2026 Major 1 — Last Chance Qualifier Session 1 (NA Central)";
const CARD_N1_LCQ1_DATE="20 апр 2026";
const _N1L=CARD_N1_LCQ_RAW.map(m1Entry);
const _N1L1=CARD_N1_LCQ1_RAW.map(m1Entry);
const _N1G=CARD_N1_GF_RAW.map(m1Entry);
_S.n1p=mkSorts(_N1P);
_S.n1l=mkSorts(_N1L);
_S.n1l1=mkSorts(_N1L1);
_S.n1g=mkSorts(_N1G);

// Each region is ranked inside its own field, so the bands match Europe's.
const n1PlayinBase = r => 96 - ((r-1)/Math.max(_N1P.length-1,1))*34;
const n1LcqLen  = () => _N1L.length + _N1L1.length;
const n1LcqBase    = r => 62 - ((r-1)/Math.max(n1LcqLen()-1,1))*14;
const n1Lcq1Base   = r => 62 - ((_N1L.length+r-1)/Math.max(n1LcqLen()-1,1))*14;
const n1GfBase     = r => 96 - ((r-1)/Math.max(_N1G.length-1,1))*26;

(function buildMajor1NAC(){
  const known=new Set();
  const add=(entry, ev, date, base, key)=>{
    // Пара, которую здесь не считают: см. CARD_WRONG_REGION.
    if(cardNotHere('m1', 'NAC', entry.duo)) return;
    CARD_DUOS_M1.push({handles:entry.duo.slice()});
    entry.duo.forEach(nm=>{
      if(known.has(nm)) return;
      known.add(nm);
      const rating=Math.round(clamp(base(entry.rank), 30, 99));
      const code = N1_NAT_LIQUI[nm] || N1_NAT_TRN[nm] || N1_LCQ1_NAT[nm] || '';
      const card={
        handle:nm, nat: code ? (CC_RU[code]||null) : null,
        natSource: N1_NAT_LIQUI[nm] ? 'liquipedia' : 'tracker',
        region:'NAC', event:ev, date:date, placement:entry.rank, note:'',
        tier:'cardmode', cardSet:'m1', rarity:rarityForRating(rating), rating,
        org: N1_ORG[nm] || null,
        real:{rank:entry.rank, pts:entry.pts, matches:entry.matches, wins:entry.wins,
              avgElims:entry.avgElims, avgPlace:entry.avgPlace, stage:key}
      };
      card['_n1'+key]=entry;
      pushCard(card);
    });
  };
  _N1P.forEach(e=>{ TEAMMATE_GROUPS.push(e.duo.slice()); add(e, CARD_N1_PLAYIN_EVENT, CARD_M1_PLAYIN_DATE, n1PlayinBase, 'Playin'); });
  _N1L.forEach(e=>add(e, CARD_N1_LCQ_EVENT, CARD_M1_LCQ_DATE, n1LcqBase, 'Lcq'));
  _N1L1.forEach(e=>add(e, CARD_N1_LCQ1_EVENT, CARD_N1_LCQ1_DATE, n1Lcq1Base, 'Lcq1'));
  _N1G.forEach(e=>add(e, CARD_N1_GF_EVENT, CARD_M1_GF_DATE, n1GfBase, 'Gf'));

  const byName={};
  (CARDS_BY_SETREG.get('m1|NAC')||[]).filter(p=>p.cardSet==='m1' && p.region==='NAC').forEach(p=>{ byName[p.handle]=p; });
  const finalists=new Set();
  _N1G.forEach(entry=>{
    CARD_DUOS_M1.unshift({handles:entry.duo.slice()});
    entry.duo.forEach(nm=>{
      const p=byName[nm]; if(!p) return;
      finalists.add(nm);
      p._n1Gf=entry; p._attrs=null; p.gfEvent=CARD_N1_GF_EVENT;
      p.realGf={rank:entry.rank, pts:entry.pts, matches:entry.matches, wins:entry.wins,
                avgElims:entry.avgElims, avgPlace:entry.avgPlace};
      p.rating=Math.round(clamp(n1GfBase(entry.rank), 30, 99));
      p.rarity=rarityForRating(p.rating);
    });
  });
  Object.keys(byName).forEach(nm=>{
    if(finalists.has(nm)) return;
    const p=byName[nm];
    p.missedGf=true;
    const base = p._n1Playin ? missedGfPlayinBase(p._n1Playin.rank, _N1P.length)
               : p._n1Lcq   ? missedGfLcqBase(p._n1Lcq.rank, _N1L.length) : p.rating-NO_GF_PENALTY;
    p.rating=Math.round(clamp(base, 30, 99));
    p.rarity=rarityForRating(p.rating);
  });
})();

