const CARD_W1_LCQ1_EVENT="FNCS 2026 Major 1 — Last Chance Qualifier Session 1 (NA West)";
const CARD_W1_LCQ1_DATE="21 апр 2026";
const _W1L=CARD_W1_LCQ_RAW.map(m1Entry);
const _W1L1=CARD_W1_LCQ1_RAW.map(m1Entry);
const _W1G=CARD_W1_GF_RAW.map(m1Entry);
_S.w1p=mkSorts(_W1P);
_S.w1l=mkSorts(_W1L);
_S.w1l1=mkSorts(_W1L1);
_S.w1g=mkSorts(_W1G);

const w1PlayinBase = r => REGION_TOP.NAW - ((r-1)/Math.max(_W1P.length-1,1))*(REGION_TOP.NAW-62);
const w1LcqLen  = () => _W1L.length + _W1L1.length;
const w1LcqBase    = r => 62 - ((r-1)/Math.max(w1LcqLen()-1,1))*14;
const w1Lcq1Base   = r => 62 - ((_W1L.length+r-1)/Math.max(w1LcqLen()-1,1))*14;
const w1GfBase     = r => REGION_TOP.NAW - ((r-1)/Math.max(_W1G.length-1,1))*(REGION_TOP.NAW-70);

(function buildMajor1NAW(){
  const known=new Set();
  const add=(entry, ev, date, base, key)=>{
    CARD_DUOS_M1.push({handles:entry.duo.slice()});
    entry.duo.forEach(nm=>{
      if(known.has(nm)) return;
      known.add(nm);
      const rating=Math.round(clamp(base(entry.rank), 30, 99));
      const code = W1_NAT_LIQUI[nm] || W1_NAT_TRN[nm] || W1_LCQ1_NAT[nm] || '';
      const card={
        handle:nm, nat: code ? (CC_RU[code]||null) : null,
        natSource: W1_NAT_LIQUI[nm] ? 'liquipedia' : 'tracker',
        region:'NAW', event:ev, date:date, placement:entry.rank, note:'',
        tier:'cardmode', cardSet:'m1', rarity:rarityForRating(rating), rating,
        org: W1_ORG[nm] || null,
        real:{rank:entry.rank, pts:entry.pts, matches:entry.matches, wins:entry.wins,
              avgElims:entry.avgElims, avgPlace:entry.avgPlace, stage:key}
      };
      card['_w1'+key]=entry;
      pushCard(card);
    });
  };
  _W1P.forEach(e=>{ TEAMMATE_GROUPS.push(e.duo.slice()); add(e, CARD_W1_PLAYIN_EVENT, CARD_M1_PLAYIN_DATE, w1PlayinBase, 'Playin'); });
  _W1L.forEach(e=>add(e, CARD_W1_LCQ_EVENT, CARD_M1_LCQ_DATE, w1LcqBase, 'Lcq'));
  _W1L1.forEach(e=>add(e, CARD_W1_LCQ1_EVENT, CARD_W1_LCQ1_DATE, w1Lcq1Base, 'Lcq1'));
  _W1G.forEach(e=>add(e, CARD_W1_GF_EVENT, CARD_M1_GF_DATE, w1GfBase, 'Gf'));

  const byName={};
  (CARDS_BY_SETREG.get('m1|NAW')||[]).filter(p=>p.cardSet==='m1' && p.region==='NAW').forEach(p=>{ byName[p.handle]=p; });
  const finalists=new Set();
  _W1G.forEach(entry=>{
    CARD_DUOS_M1.unshift({handles:entry.duo.slice()});
    entry.duo.forEach(nm=>{
      const p=byName[nm]; if(!p) return;
      finalists.add(nm);
      p._w1Gf=entry; p._attrs=null; p.gfEvent=CARD_W1_GF_EVENT;
      p.realGf={rank:entry.rank, pts:entry.pts, matches:entry.matches, wins:entry.wins,
                avgElims:entry.avgElims, avgPlace:entry.avgPlace};
      p.rating=Math.round(clamp(w1GfBase(entry.rank), 30, 99));
      p.rarity=rarityForRating(p.rating);
    });
  });
  Object.keys(byName).forEach(nm=>{
    if(finalists.has(nm)) return;
    const p=byName[nm];
    p.missedGf=true;
    const base = p._w1Playin ? missedGfPlayinBase(p._w1Playin.rank, _W1P.length)
               : p._w1Lcq   ? missedGfLcqBase(p._w1Lcq.rank, _W1L.length) : p.rating-NO_GF_PENALTY;
    p.rating=Math.round(clamp(base, 30, 99));
    p.rarity=rarityForRating(p.rating);
  });
})();

