const CARD_B1_LCQ1_EVENT="FNCS 2026 Major 1 — Last Chance Qualifier Session 1 (Brazil)";
const CARD_B1_LCQ1_DATE="20 апр 2026";
const _B1L=CARD_B1_LCQ_RAW.map(m1Entry);
const _B1L1=CARD_B1_LCQ1_RAW.map(m1Entry);
const _B1G=CARD_B1_GF_RAW.map(m1Entry);
_S.b1p=mkSorts(_B1P);
_S.b1l=mkSorts(_B1L);
_S.b1l1=mkSorts(_B1L1);
_S.b1g=mkSorts(_B1G);

const b1PlayinBase = r => REGION_TOP.BR - ((r-1)/Math.max(_B1P.length-1,1))*(REGION_TOP.BR-62);
const b1LcqLen  = () => _B1L.length + _B1L1.length;
const b1LcqBase    = r => 62 - ((r-1)/Math.max(b1LcqLen()-1,1))*14;
const b1Lcq1Base   = r => 62 - ((_B1L.length+r-1)/Math.max(b1LcqLen()-1,1))*14;
const b1GfBase     = r => REGION_TOP.BR - ((r-1)/Math.max(_B1G.length-1,1))*(REGION_TOP.BR-70);

(function buildMajor1BR(){
  const known=new Set();
  const add=(entry, ev, date, base, key)=>{
    CARD_DUOS_M1.push({handles:entry.duo.slice()});
    entry.duo.forEach(nm=>{
      if(known.has(nm)) return;
      known.add(nm);
      const rating=Math.round(clamp(base(entry.rank), 30, 99));
      const code = B1_NAT_LIQUI[nm] || B1_NAT_TRN[nm] || B1_LCQ1_NAT[nm] || '';
      const card={
        handle:nm, nat: code ? (CC_RU[code]||null) : null,
        natSource: B1_NAT_LIQUI[nm] ? 'liquipedia' : 'tracker',
        region:'BR', event:ev, date:date, placement:entry.rank, note:'',
        tier:'cardmode', cardSet:'m1', rarity:rarityForRating(rating), rating,
        org: B1_ORG[nm] || null,
        real:{rank:entry.rank, pts:entry.pts, matches:entry.matches, wins:entry.wins,
              avgElims:entry.avgElims, avgPlace:entry.avgPlace, stage:key}
      };
      card['_b1'+key]=entry;
      pushCard(card);
    });
  };
  _B1P.forEach(e=>{ TEAMMATE_GROUPS.push(e.duo.slice()); add(e, CARD_B1_PLAYIN_EVENT, CARD_M1_PLAYIN_DATE, b1PlayinBase, 'Playin'); });
  _B1L.forEach(e=>add(e, CARD_B1_LCQ_EVENT, CARD_M1_LCQ_DATE, b1LcqBase, 'Lcq'));
  _B1L1.forEach(e=>add(e, CARD_B1_LCQ1_EVENT, CARD_B1_LCQ1_DATE, b1Lcq1Base, 'Lcq1'));
  _B1G.forEach(e=>add(e, CARD_B1_GF_EVENT, CARD_M1_GF_DATE, b1GfBase, 'Gf'));

  const byName={};
  (CARDS_BY_SETREG.get('m1|BR')||[]).filter(p=>p.cardSet==='m1' && p.region==='BR').forEach(p=>{ byName[p.handle]=p; });
  const finalists=new Set();
  _B1G.forEach(entry=>{
    CARD_DUOS_M1.unshift({handles:entry.duo.slice()});
    entry.duo.forEach(nm=>{
      const p=byName[nm]; if(!p) return;
      finalists.add(nm);
      p._b1Gf=entry; p._attrs=null; p.gfEvent=CARD_B1_GF_EVENT;
      p.realGf={rank:entry.rank, pts:entry.pts, matches:entry.matches, wins:entry.wins,
                avgElims:entry.avgElims, avgPlace:entry.avgPlace};
      p.rating=Math.round(clamp(b1GfBase(entry.rank), 30, 99));
      p.rarity=rarityForRating(p.rating);
    });
  });
  Object.keys(byName).forEach(nm=>{
    if(finalists.has(nm)) return;
    const p=byName[nm];
    p.missedGf=true;
    const base = p._b1Playin ? missedGfPlayinBase(p._b1Playin.rank, _B1P.length)
               : p._b1Lcq   ? missedGfLcqBase(p._b1Lcq.rank, _B1L.length) : p.rating-NO_GF_PENALTY;
    p.rating=Math.round(clamp(base, 30, 99));
    p.rarity=rarityForRating(p.rating);
  });
})();

