const o1Lcq1Base   = r => 62 - ((_O1L.length+r-1)/Math.max(o1LcqLen()-1,1))*14;
const o1GfBase     = r => REGION_TOP.OCE - ((r-1)/Math.max(_O1G.length-1,1))*(REGION_TOP.OCE-70);

(function buildMajor1OCE(){
  const known=new Set();
  const add=(entry, ev, date, base, key)=>{
    CARD_DUOS_M1.push({handles:entry.duo.slice()});
    entry.duo.forEach(nm=>{
      if(known.has(nm)) return;
      known.add(nm);
      const rating=Math.round(clamp(base(entry.rank), 30, 99));
      const code = O1_NAT_LIQUI[nm] || O1_NAT_TRN[nm] || O1_LCQ1_NAT[nm] || '';
      const card={
        handle:nm, nat: code ? (CC_RU[code]||null) : null,
        natSource: O1_NAT_LIQUI[nm] ? 'liquipedia' : 'tracker',
        region:'OCE', event:ev, date:date, placement:entry.rank, note:'',
        tier:'cardmode', cardSet:'m1', rarity:rarityForRating(rating), rating,
        org: O1_ORG[nm] || null,
        real:{rank:entry.rank, pts:entry.pts, matches:entry.matches, wins:entry.wins,
              avgElims:entry.avgElims, avgPlace:entry.avgPlace, stage:key}
      };
      card['_o1'+key]=entry;
      pushCard(card);
    });
  };
  _O1P.forEach(e=>{ TEAMMATE_GROUPS.push(e.duo.slice()); add(e, CARD_O1_PLAYIN_EVENT, CARD_M1_PLAYIN_DATE, o1PlayinBase, 'Playin'); });
  _O1L.forEach(e=>add(e, CARD_O1_LCQ_EVENT, CARD_M1_LCQ_DATE, o1LcqBase, 'Lcq'));
  _O1L1.forEach(e=>add(e, CARD_O1_LCQ1_EVENT, CARD_O1_LCQ1_DATE, o1Lcq1Base, 'Lcq1'));
  _O1G.forEach(e=>add(e, CARD_O1_GF_EVENT, CARD_M1_GF_DATE, o1GfBase, 'Gf'));

  const byName={};
  (CARDS_BY_SETREG.get('m1|OCE')||[]).filter(p=>p.cardSet==='m1' && p.region==='OCE').forEach(p=>{ byName[p.handle]=p; });
  const finalists=new Set();
  _O1G.forEach(entry=>{
    CARD_DUOS_M1.unshift({handles:entry.duo.slice()});
    entry.duo.forEach(nm=>{
      const p=byName[nm]; if(!p) return;
      finalists.add(nm);
      p._o1Gf=entry; p._attrs=null; p.gfEvent=CARD_O1_GF_EVENT;
      p.realGf={rank:entry.rank, pts:entry.pts, matches:entry.matches, wins:entry.wins,
                avgElims:entry.avgElims, avgPlace:entry.avgPlace};
      p.rating=Math.round(clamp(o1GfBase(entry.rank), 30, 99));
      p.rarity=rarityForRating(p.rating);
    });
  });
  Object.keys(byName).forEach(nm=>{
    if(finalists.has(nm)) return;
    const p=byName[nm];
    p.missedGf=true;
    const base = p._o1Playin ? missedGfPlayinBase(p._o1Playin.rank, _O1P.length)
               : p._o1Lcq   ? missedGfLcqBase(p._o1Lcq.rank, _O1L.length) : p.rating-NO_GF_PENALTY;
    p.rating=Math.round(clamp(base, 30, 99));
    p.rarity=rarityForRating(p.rating);
  });
})();

