const CARD_A1_LCQ1_EVENT="FNCS 2026 Major 1 — Last Chance Qualifier Session 1 (Asia)";
const CARD_A1_LCQ1_DATE="20 апр 2026";
const _A1L=CARD_A1_LCQ_RAW.map(m1Entry);
const _A1L1=CARD_A1_LCQ1_RAW.map(m1Entry);
const _A1G=CARD_A1_GF_RAW.map(m1Entry);
_S.a1p=mkSorts(_A1P);
_S.a1l=mkSorts(_A1L);
_S.a1l1=mkSorts(_A1L1);
_S.a1g=mkSorts(_A1G);

const a1PlayinBase = r => REGION_TOP.ASIA - ((r-1)/Math.max(_A1P.length-1,1))*(REGION_TOP.ASIA-62);
const a1LcqLen  = () => _A1L.length + _A1L1.length;
const a1LcqBase    = r => 62 - ((r-1)/Math.max(a1LcqLen()-1,1))*14;
const a1Lcq1Base   = r => 62 - ((_A1L.length+r-1)/Math.max(a1LcqLen()-1,1))*14;
const a1GfBase     = r => REGION_TOP.ASIA - ((r-1)/Math.max(_A1G.length-1,1))*(REGION_TOP.ASIA-70);

(function buildMajor1ASIA(){
  const known=new Set();
  const add=(entry, ev, date, base, key)=>{
    CARD_DUOS_M1.push({handles:entry.duo.slice()});
    entry.duo.forEach(nm=>{
      if(known.has(nm)) return;
      known.add(nm);
      const rating=Math.round(clamp(base(entry.rank), 30, 99));
      const code = A1_NAT_LIQUI[nm] || A1_NAT_TRN[nm] || A1_LCQ1_NAT[nm] || '';
      const card={
        handle:nm, nat: code ? (CC_RU[code]||null) : null,
        natSource: A1_NAT_LIQUI[nm] ? 'liquipedia' : 'tracker',
        region:'ASIA', event:ev, date:date, placement:entry.rank, note:'',
        tier:'cardmode', cardSet:'m1', rarity:rarityForRating(rating), rating,
        org: A1_ORG[nm] || null,
        real:{rank:entry.rank, pts:entry.pts, matches:entry.matches, wins:entry.wins,
              avgElims:entry.avgElims, avgPlace:entry.avgPlace, stage:key}
      };
      card['_a1'+key]=entry;
      pushCard(card);
    });
  };
  _A1P.forEach(e=>{ TEAMMATE_GROUPS.push(e.duo.slice()); add(e, CARD_A1_PLAYIN_EVENT, CARD_M1_PLAYIN_DATE, a1PlayinBase, 'Playin'); });
  _A1L.forEach(e=>add(e, CARD_A1_LCQ_EVENT, CARD_M1_LCQ_DATE, a1LcqBase, 'Lcq'));
  _A1L1.forEach(e=>add(e, CARD_A1_LCQ1_EVENT, CARD_A1_LCQ1_DATE, a1Lcq1Base, 'Lcq1'));
  _A1G.forEach(e=>add(e, CARD_A1_GF_EVENT, CARD_M1_GF_DATE, a1GfBase, 'Gf'));

  const byName={};
  (CARDS_BY_SETREG.get('m1|ASIA')||[]).filter(p=>p.cardSet==='m1' && p.region==='ASIA').forEach(p=>{ byName[p.handle]=p; });
  const finalists=new Set();
  _A1G.forEach(entry=>{
    CARD_DUOS_M1.unshift({handles:entry.duo.slice()});
    entry.duo.forEach(nm=>{
      const p=byName[nm]; if(!p) return;
      finalists.add(nm);
      p._a1Gf=entry; p._attrs=null; p.gfEvent=CARD_A1_GF_EVENT;
      p.realGf={rank:entry.rank, pts:entry.pts, matches:entry.matches, wins:entry.wins,
                avgElims:entry.avgElims, avgPlace:entry.avgPlace};
      p.rating=Math.round(clamp(a1GfBase(entry.rank), 30, 99));
      p.rarity=rarityForRating(p.rating);
    });
  });
  Object.keys(byName).forEach(nm=>{
    if(finalists.has(nm)) return;
    const p=byName[nm];
    p.missedGf=true;
    const base = p._a1Playin ? missedGfPlayinBase(p._a1Playin.rank, _A1P.length)
               : p._a1Lcq   ? missedGfLcqBase(p._a1Lcq.rank, _A1L.length) : p.rating-NO_GF_PENALTY;
    p.rating=Math.round(clamp(base, 30, 99));
    p.rarity=rarityForRating(p.rating);
  });
})();

