const CARD_E1_LCQ1_EVENT="FNCS 2026 Major 1 — Last Chance Qualifier Session 1 (Middle East)";
const CARD_E1_LCQ1_DATE="20 апр 2026";
const _E1L=CARD_E1_LCQ_RAW.map(m1Entry);
const _E1L1=CARD_E1_LCQ1_RAW.map(m1Entry);
const _E1G=CARD_E1_GF_RAW.map(m1Entry);
_S.e1p=mkSorts(_E1P);
_S.e1l=mkSorts(_E1L);
_S.e1l1=mkSorts(_E1L1);
_S.e1g=mkSorts(_E1G);

const e1PlayinBase = r => REGION_TOP.ME - ((r-1)/Math.max(_E1P.length-1,1))*(REGION_TOP.ME-62);
const e1LcqLen  = () => _E1L.length + _E1L1.length;
const e1LcqBase    = r => 62 - ((r-1)/Math.max(e1LcqLen()-1,1))*14;
const e1Lcq1Base   = r => 62 - ((_E1L.length+r-1)/Math.max(e1LcqLen()-1,1))*14;
const e1GfBase     = r => REGION_TOP.ME - ((r-1)/Math.max(_E1G.length-1,1))*(REGION_TOP.ME-70);

(function buildMajor1ME(){
  const known=new Set();
  const add=(entry, ev, date, base, key)=>{
    CARD_DUOS_M1.push({handles:entry.duo.slice()});
    entry.duo.forEach(nm=>{
      if(known.has(nm)) return;
      known.add(nm);
      const rating=Math.round(clamp(base(entry.rank), 30, 99));
      const code = E1_NAT_LIQUI[nm] || E1_NAT_TRN[nm] || E1_LCQ1_NAT[nm] || '';
      const card={
        handle:nm, nat: code ? (CC_RU[code]||null) : null,
        natSource: E1_NAT_LIQUI[nm] ? 'liquipedia' : 'tracker',
        region:'ME', event:ev, date:date, placement:entry.rank, note:'',
        tier:'cardmode', cardSet:'m1', rarity:rarityForRating(rating), rating,
        org: E1_ORG[nm] || null,
        real:{rank:entry.rank, pts:entry.pts, matches:entry.matches, wins:entry.wins,
              avgElims:entry.avgElims, avgPlace:entry.avgPlace, stage:key}
      };
      card['_e1'+key]=entry;
      pushCard(card);
    });
  };
  _E1P.forEach(e=>{ TEAMMATE_GROUPS.push(e.duo.slice()); add(e, CARD_E1_PLAYIN_EVENT, CARD_M1_PLAYIN_DATE, e1PlayinBase, 'Playin'); });
  _E1L.forEach(e=>add(e, CARD_E1_LCQ_EVENT, CARD_M1_LCQ_DATE, e1LcqBase, 'Lcq'));
  _E1L1.forEach(e=>add(e, CARD_E1_LCQ1_EVENT, CARD_E1_LCQ1_DATE, e1Lcq1Base, 'Lcq1'));
  _E1G.forEach(e=>add(e, CARD_E1_GF_EVENT, CARD_M1_GF_DATE, e1GfBase, 'Gf'));

  const byName={};
  (CARDS_BY_SETREG.get('m1|ME')||[]).filter(p=>p.cardSet==='m1' && p.region==='ME').forEach(p=>{ byName[p.handle]=p; });
  const finalists=new Set();
  _E1G.forEach(entry=>{
    CARD_DUOS_M1.unshift({handles:entry.duo.slice()});
    entry.duo.forEach(nm=>{
      const p=byName[nm]; if(!p) return;
      finalists.add(nm);
      p._e1Gf=entry; p._attrs=null; p.gfEvent=CARD_E1_GF_EVENT;
      p.realGf={rank:entry.rank, pts:entry.pts, matches:entry.matches, wins:entry.wins,
                avgElims:entry.avgElims, avgPlace:entry.avgPlace};
      p.rating=Math.round(clamp(e1GfBase(entry.rank), 30, 99));
      p.rarity=rarityForRating(p.rating);
    });
  });
  Object.keys(byName).forEach(nm=>{
    if(finalists.has(nm)) return;
    const p=byName[nm];
    p.missedGf=true;
    const base = p._e1Playin ? missedGfPlayinBase(p._e1Playin.rank, _E1P.length)
               : p._e1Lcq   ? missedGfLcqBase(p._e1Lcq.rank, _E1L.length) : p.rating-NO_GF_PENALTY;
    p.rating=Math.round(clamp(base, 30, 99));
    p.rarity=rarityForRating(p.rating);
  });
})();

// Everything built before this point belongs to the Major 2 set.
PLAYERS_BASE.forEach(p=>{ if(p.tier==='cardmode' && !p.cardSet) p.cardSet='m2'; });

