const CARD_M2_LCQ1_EVENT="FNCS 2026 Major 2 — Last Chance Qualifier Session 1 (Europe)";
const CARD_M2_LCQ1_DATE="27 июл 2026";
const _M2L=CARD_M2_LCQ_RAW.map(m1Entry);
const _M2L1=CARD_M2_LCQ1_RAW.map(m1Entry);
const _M2G=CARD_M2_GF_RAW.map(m1Entry);
_S.m2p=mkSorts(_M2P);
_S.m2l=mkSorts(_M2L);
_S.m2l1=mkSorts(_M2L1);
_S.m2g=mkSorts(_M2G);

const m2PlayinBase = r => REGION_TOP.EU - ((r-1)/Math.max(_M2P.length-1,1))*(REGION_TOP.EU-62);
const m2LcqLen  = () => _M2L.length + _M2L1.length;
const m2LcqBase    = r => 62 - ((r-1)/Math.max(m2LcqLen()-1,1))*14;
const m2Lcq1Base   = r => 62 - ((_M2L.length+r-1)/Math.max(m2LcqLen()-1,1))*14;
const m2GfBase     = r => REGION_TOP.EU - ((r-1)/Math.max(_M2G.length-1,1))*(REGION_TOP.EU-70);

(function buildMajor2EU(){
  const known=new Set();
  const add=(entry, ev, date, base, key)=>{
    CARD_DUOS.push({handles:entry.duo.slice()});
    entry.duo.forEach(nm=>{
      if(known.has(nm)) return;
      known.add(nm);
      const rating=Math.round(clamp(base(entry.rank), 30, 99));
      const code = M2_NAT_LIQUI[nm] || M2_NAT_TRN[nm] || M2_LCQ1_NAT[nm] || '';
      const card={
        handle:nm, nat: code ? (CC_RU[code]||null) : null,
        natSource: M2_NAT_LIQUI[nm] ? 'liquipedia' : 'tracker',
        region:'EU', event:ev, date:date, placement:entry.rank, note:'',
        tier:'cardmode', cardSet:'m2', rarity:rarityForRating(rating), rating,
        org: M2_ORG[nm] || null,
        real:{rank:entry.rank, pts:entry.pts, matches:entry.matches, wins:entry.wins,
              avgElims:entry.avgElims, avgPlace:entry.avgPlace, stage:key}
      };
      card['_m2'+key]=entry;
      pushCard(card);
    });
  };
  _M2P.forEach(e=>{ TEAMMATE_GROUPS.push(e.duo.slice()); add(e, CARD_M2_PLAYIN_EVENT, CARD_M2_PLAYIN_DATE, m2PlayinBase, 'Playin'); });
  _M2L.forEach(e=>add(e, CARD_M2_LCQ_EVENT, CARD_M2_LCQ_DATE, m2LcqBase, 'Lcq'));
  _M2L1.forEach(e=>add(e, CARD_M2_LCQ1_EVENT, CARD_M2_LCQ1_DATE, m2Lcq1Base, 'Lcq1'));
  _M2G.forEach(e=>add(e, CARD_M2_GF_EVENT, CARD_M2_GF_DATE, m2GfBase, 'Gf'));

  const byName={};
  (CARDS_BY_SETREG.get('m2|EU')||[]).filter(p=>p.cardSet==='m2' && p.region==='EU').forEach(p=>{ byName[p.handle]=p; });
  const finalists=new Set();
  _M2G.forEach(entry=>{
    CARD_DUOS.unshift({handles:entry.duo.slice()});
    entry.duo.forEach(nm=>{
      const p=byName[nm]; if(!p) return;
      finalists.add(nm);
      p._m2Gf=entry; p._attrs=null; p.gfEvent=CARD_M2_GF_EVENT;
      p.realGf={rank:entry.rank, pts:entry.pts, matches:entry.matches, wins:entry.wins,
                avgElims:entry.avgElims, avgPlace:entry.avgPlace};
      p.rating=Math.round(clamp(m2GfBase(entry.rank), 30, 99));
      p.rarity=rarityForRating(p.rating);
    });
  });
  Object.keys(byName).forEach(nm=>{
    if(finalists.has(nm)) return;
    const p=byName[nm];
    p.missedGf=true;
    const base = p._m2Playin ? missedGfPlayinBase(p._m2Playin.rank, _M2P.length)
               : p._m2Lcq   ? missedGfLcqBase(p._m2Lcq.rank, _M2L.length) : p.rating-NO_GF_PENALTY;
    p.rating=Math.round(clamp(base, 30, 99));
    p.rarity=rarityForRating(p.rating);
  });
})();

