_S.n2p=mkSorts(_N2P);
_S.n2l=mkSorts(_N2L);
_S.n2l1=mkSorts(_N2L1);
_S.n2g=mkSorts(_N2G);

// NA Central is as deep a region as Europe, so it gets the same rating bands.
const n2PlayinBase = r => REGION_TOP.NAC - ((r-1)/Math.max(_N2P.length-1,1))*(REGION_TOP.NAC-62);
const n2LcqLen  = () => _N2L.length + _N2L1.length;
const n2LcqBase    = r => 62 - ((r-1)/Math.max(n2LcqLen()-1,1))*14;
const n2Lcq1Base   = r => 62 - ((_N2L.length+r-1)/Math.max(n2LcqLen()-1,1))*14;
const n2GfBase     = r => REGION_TOP.NAC - ((r-1)/Math.max(_N2G.length-1,1))*(REGION_TOP.NAC-70);

(function buildMajor2NAC(){
  const known=new Set();
  const add=(entry, ev, date, base, key)=>{
    CARD_DUOS.push({handles:entry.duo.slice()});
    entry.duo.forEach(nm=>{
      if(known.has(nm)) return;
      known.add(nm);
      const rating=Math.round(clamp(base(entry.rank), 30, 99));
      const code = N2_NAT_LIQUI[nm] || N2_NAT_TRN[nm] || N2_LCQ1_NAT[nm] || '';
      const card={
        handle:nm, nat: code ? (CC_RU[code]||null) : null,
        natSource: N2_NAT_LIQUI[nm] ? 'liquipedia' : 'tracker',
        liquiName: N2_LIQUI_NAME[nm] || null,
        region:'NAC', event:ev, date:date, placement:entry.rank, note:'',
        tier:'cardmode', cardSet:'m2', rarity:rarityForRating(rating), rating,
        org: N2_ORG[nm] || null,
        real:{rank:entry.rank, pts:entry.pts, matches:entry.matches, wins:entry.wins,
              avgElims:entry.avgElims, avgPlace:entry.avgPlace, stage:key}
      };
      card['_n2'+key]=entry;
      pushCard(card);
    });
  };
  _N2P.forEach(e=>{ TEAMMATE_GROUPS.push(e.duo.slice()); add(e, CARD_N2_PLAYIN_EVENT, CARD_M2_PLAYIN_DATE, n2PlayinBase, 'Playin'); });
  _N2L.forEach(e=>add(e, CARD_N2_LCQ_EVENT, CARD_M2_LCQ_DATE, n2LcqBase, 'Lcq'));
  _N2L1.forEach(e=>add(e, CARD_N2_LCQ1_EVENT, CARD_N2_LCQ1_DATE, n2Lcq1Base, 'Lcq1'));
  _N2G.forEach(e=>add(e, CARD_N2_GF_EVENT, CARD_M2_GF_DATE, n2GfBase, 'Gf'));

  const byName={};
  (CARDS_BY_SETREG.get('m2|NAC')||[]).filter(p=>p.cardSet==='m2' && p.region==='NAC').forEach(p=>{ byName[p.handle]=p; });
  const finalists=new Set();
  _N2G.forEach(entry=>{
    CARD_DUOS.unshift({handles:entry.duo.slice()});
    entry.duo.forEach(nm=>{
      const p=byName[nm]; if(!p) return;
      finalists.add(nm);
      p._n2Gf=entry; p._attrs=null; p.gfEvent=CARD_N2_GF_EVENT;
      p.realGf={rank:entry.rank, pts:entry.pts, matches:entry.matches, wins:entry.wins,
                avgElims:entry.avgElims, avgPlace:entry.avgPlace};
      p.rating=Math.round(clamp(n2GfBase(entry.rank), 30, 99));
      p.rarity=rarityForRating(p.rating);
    });
  });
  Object.keys(byName).forEach(nm=>{
    if(finalists.has(nm)) return;
    const p=byName[nm];
    p.missedGf=true;
    const base = p._n2Playin ? missedGfPlayinBase(p._n2Playin.rank, _N2P.length)
               : p._n2Lcq   ? missedGfLcqBase(p._n2Lcq.rank, _N2L.length) : p.rating-NO_GF_PENALTY;
    p.rating=Math.round(clamp(base, 30, 99));
    p.rarity=rarityForRating(p.rating);
  });
})();

