const CARD_W2_LCQ1_EVENT="FNCS 2026 Major 2 — Last Chance Qualifier Session 1 (NA West)";
const CARD_W2_LCQ1_DATE="28 июл 2026";
const _W2L=CARD_W2_LCQ_RAW.map(m1Entry);
const _W2L1=CARD_W2_LCQ1_RAW.map(m1Entry);
const _W2G=CARD_W2_GF_RAW.map(m1Entry);
_S.w2p=mkSorts(_W2P);
_S.w2l=mkSorts(_W2L);
_S.w2l1=mkSorts(_W2L1);
_S.w2g=mkSorts(_W2G);

// Ranked inside its own field, against the band REGION_TOP sets for NAW.
const w2PlayinBase = r => REGION_TOP.NAW - ((r-1)/Math.max(_W2P.length-1,1))*(REGION_TOP.NAW-62);
const w2LcqLen  = () => _W2L.length + _W2L1.length;
const w2LcqBase    = r => 62 - ((r-1)/Math.max(w2LcqLen()-1,1))*14;
const w2Lcq1Base   = r => 62 - ((_W2L.length+r-1)/Math.max(w2LcqLen()-1,1))*14;
const w2GfBase     = r => REGION_TOP.NAW - ((r-1)/Math.max(_W2G.length-1,1))*(REGION_TOP.NAW-70);

(function buildMajor2NAW(){
  const known=new Set();
  const add=(entry, ev, date, base, key)=>{
    CARD_DUOS.push({handles:entry.duo.slice()});
    entry.duo.forEach(nm=>{
      if(known.has(nm)) return;
      known.add(nm);
      const rating=Math.round(clamp(base(entry.rank), 30, 99));
      const code = W2_NAT_LIQUI[nm] || W2_NAT_TRN[nm] || W2_LCQ1_NAT[nm] || '';
      const card={
        handle:nm, nat: code ? (CC_RU[code]||null) : null,
        natSource: W2_NAT_LIQUI[nm] ? 'liquipedia' : 'tracker',
        liquiName: W2_LIQUI_NAME[nm] || null,
        region:'NAW', event:ev, date:date, placement:entry.rank, note:'',
        tier:'cardmode', cardSet:'m2', rarity:rarityForRating(rating), rating,
        org: W2_ORG[nm] || null,
        real:{rank:entry.rank, pts:entry.pts, matches:entry.matches, wins:entry.wins,
              avgElims:entry.avgElims, avgPlace:entry.avgPlace, stage:key}
      };
      card['_w2'+key]=entry;
      pushCard(card);
    });
  };
  _W2P.forEach(e=>{ TEAMMATE_GROUPS.push(e.duo.slice()); add(e, CARD_W2_PLAYIN_EVENT, CARD_M2_PLAYIN_DATE, w2PlayinBase, 'Playin'); });
  _W2L.forEach(e=>add(e, CARD_W2_LCQ_EVENT, CARD_M2_LCQ_DATE, w2LcqBase, 'Lcq'));
  _W2L1.forEach(e=>add(e, CARD_W2_LCQ1_EVENT, CARD_W2_LCQ1_DATE, w2Lcq1Base, 'Lcq1'));
  _W2G.forEach(e=>add(e, CARD_W2_GF_EVENT, CARD_M2_GF_DATE, w2GfBase, 'Gf'));

  const byName={};
  (CARDS_BY_SETREG.get('m2|NAW')||[]).filter(p=>p.cardSet==='m2' && p.region==='NAW').forEach(p=>{ byName[p.handle]=p; });
  const finalists=new Set();
  _W2G.forEach(entry=>{
    CARD_DUOS.unshift({handles:entry.duo.slice()});
    entry.duo.forEach(nm=>{
      const p=byName[nm]; if(!p) return;
      finalists.add(nm);
      p._w2Gf=entry; p._attrs=null; p.gfEvent=CARD_W2_GF_EVENT;
      p.realGf={rank:entry.rank, pts:entry.pts, matches:entry.matches, wins:entry.wins,
                avgElims:entry.avgElims, avgPlace:entry.avgPlace};
      p.rating=Math.round(clamp(w2GfBase(entry.rank), 30, 99));
      p.rarity=rarityForRating(p.rating);
    });
  });
  Object.keys(byName).forEach(nm=>{
    if(finalists.has(nm)) return;
    const p=byName[nm];
    p.missedGf=true;
    const base = p._w2Playin ? missedGfPlayinBase(p._w2Playin.rank, _W2P.length)
               : p._w2Lcq   ? missedGfLcqBase(p._w2Lcq.rank, _W2L.length) : p.rating-NO_GF_PENALTY;
    p.rating=Math.round(clamp(base, 30, 99));
    p.rarity=rarityForRating(p.rating);
  });
})();


