_S.b2g=mkSorts(_B2G);

// Ranked inside its own field, against the band REGION_TOP sets for BR.
const b2PlayinBase = r => REGION_TOP.BR - ((r-1)/Math.max(_B2P.length-1,1))*(REGION_TOP.BR-62);
const b2LcqLen  = () => _B2L.length + _B2L1.length;
const b2LcqBase    = r => 62 - ((r-1)/Math.max(b2LcqLen()-1,1))*14;
const b2Lcq1Base   = r => 62 - ((_B2L.length+r-1)/Math.max(b2LcqLen()-1,1))*14;
const b2GfBase     = r => REGION_TOP.BR - ((r-1)/Math.max(_B2G.length-1,1))*(REGION_TOP.BR-70);

(function buildMajor2BR(){
  const known=new Set();
  const add=(entry, ev, date, base, key)=>{
    CARD_DUOS.push({handles:entry.duo.slice()});
    entry.duo.forEach(nm=>{
      if(known.has(nm)) return;
      known.add(nm);
      const rating=Math.round(clamp(base(entry.rank), 30, 99));
      const code = B2_NAT_LIQUI[nm] || B2_NAT_TRN[nm] || B2_LCQ1_NAT[nm] || '';
      const card={
        handle:nm, nat: code ? (CC_RU[code]||null) : null,
        natSource: B2_NAT_LIQUI[nm] ? 'liquipedia' : 'tracker',
        liquiName: B2_LIQUI_NAME[nm] || null,
        region:'BR', event:ev, date:date, placement:entry.rank, note:'',
        tier:'cardmode', cardSet:'m2', rarity:rarityForRating(rating), rating,
        org: B2_ORG[nm] || null,
        real:{rank:entry.rank, pts:entry.pts, matches:entry.matches, wins:entry.wins,
              avgElims:entry.avgElims, avgPlace:entry.avgPlace, stage:key}
      };
      card['_b2'+key]=entry;
      pushCard(card);
    });
  };
  _B2P.forEach(e=>{ TEAMMATE_GROUPS.push(e.duo.slice()); add(e, CARD_B2_PLAYIN_EVENT, CARD_M2_PLAYIN_DATE, b2PlayinBase, 'Playin'); });
  _B2L.forEach(e=>add(e, CARD_B2_LCQ_EVENT, CARD_M2_LCQ_DATE, b2LcqBase, 'Lcq'));
  _B2L1.forEach(e=>add(e, CARD_B2_LCQ1_EVENT, CARD_B2_LCQ1_DATE, b2Lcq1Base, 'Lcq1'));
  _B2G.forEach(e=>add(e, CARD_B2_GF_EVENT, CARD_M2_GF_DATE, b2GfBase, 'Gf'));

  const byName={};
  (CARDS_BY_SETREG.get('m2|BR')||[]).filter(p=>p.cardSet==='m2' && p.region==='BR').forEach(p=>{ byName[p.handle]=p; });
  const finalists=new Set();
  _B2G.forEach(entry=>{
    CARD_DUOS.unshift({handles:entry.duo.slice()});
    entry.duo.forEach(nm=>{
      const p=byName[nm]; if(!p) return;
      finalists.add(nm);
      p._b2Gf=entry; p._attrs=null; p.gfEvent=CARD_B2_GF_EVENT;
      p.realGf={rank:entry.rank, pts:entry.pts, matches:entry.matches, wins:entry.wins,
                avgElims:entry.avgElims, avgPlace:entry.avgPlace};
      p.rating=Math.round(clamp(b2GfBase(entry.rank), 30, 99));
      p.rarity=rarityForRating(p.rating);
    });
  });
  Object.keys(byName).forEach(nm=>{
    if(finalists.has(nm)) return;
    const p=byName[nm];
    p.missedGf=true;
    const base = p._b2Playin ? missedGfPlayinBase(p._b2Playin.rank, _B2P.length)
               : p._b2Lcq   ? missedGfLcqBase(p._b2Lcq.rank, _B2L.length) : p.rating-NO_GF_PENALTY;
    p.rating=Math.round(clamp(base, 30, 99));
    p.rarity=rarityForRating(p.rating);
  });
})();


