const CARD_A2_LCQ1_EVENT="FNCS 2026 Major 2 — Last Chance Qualifier Session 1 (Asia)";
const CARD_A2_LCQ1_DATE="27 июл 2026";
const _A2L=CARD_A2_LCQ_RAW.map(m1Entry);
const _A2L1=CARD_A2_LCQ1_RAW.map(m1Entry);
const _A2G=CARD_A2_GF_RAW.map(m1Entry);
_S.a2p=mkSorts(_A2P);
_S.a2l=mkSorts(_A2L);
_S.a2l1=mkSorts(_A2L1);
_S.a2g=mkSorts(_A2G);

// Ranked inside its own field, against the band REGION_TOP sets for ASIA.
const a2PlayinBase = r => REGION_TOP.ASIA - ((r-1)/Math.max(_A2P.length-1,1))*(REGION_TOP.ASIA-62);
const a2LcqLen  = () => _A2L.length + _A2L1.length;
const a2LcqBase    = r => 62 - ((r-1)/Math.max(a2LcqLen()-1,1))*14;
const a2Lcq1Base   = r => 62 - ((_A2L.length+r-1)/Math.max(a2LcqLen()-1,1))*14;
const a2GfBase     = r => REGION_TOP.ASIA - ((r-1)/Math.max(_A2G.length-1,1))*(REGION_TOP.ASIA-70);

(function buildMajor2ASIA(){
  const known=new Set();
  const add=(entry, ev, date, base, key)=>{
    CARD_DUOS.push({handles:entry.duo.slice()});
    entry.duo.forEach(nm=>{
      if(known.has(nm)) return;
      known.add(nm);
      const rating=Math.round(clamp(base(entry.rank), 30, 99));
      const code = A2_NAT_LIQUI[nm] || A2_NAT_TRN[nm] || A2_LCQ1_NAT[nm] || '';
      const card={
        handle:nm, nat: code ? (CC_RU[code]||null) : null,
        natSource: A2_NAT_LIQUI[nm] ? 'liquipedia' : 'tracker',
        liquiName: A2_LIQUI_NAME[nm] || null,
        region:'ASIA', event:ev, date:date, placement:entry.rank, note:'',
        tier:'cardmode', cardSet:'m2', rarity:rarityForRating(rating), rating,
        org: A2_ORG[nm] || null,
        real:{rank:entry.rank, pts:entry.pts, matches:entry.matches, wins:entry.wins,
              avgElims:entry.avgElims, avgPlace:entry.avgPlace, stage:key}
      };
      card['_a2'+key]=entry;
      pushCard(card);
    });
  };
  _A2P.forEach(e=>{ TEAMMATE_GROUPS.push(e.duo.slice()); add(e, CARD_A2_PLAYIN_EVENT, CARD_M2_PLAYIN_DATE, a2PlayinBase, 'Playin'); });
  _A2L.forEach(e=>add(e, CARD_A2_LCQ_EVENT, CARD_M2_LCQ_DATE, a2LcqBase, 'Lcq'));
  _A2L1.forEach(e=>add(e, CARD_A2_LCQ1_EVENT, CARD_A2_LCQ1_DATE, a2Lcq1Base, 'Lcq1'));
  _A2G.forEach(e=>add(e, CARD_A2_GF_EVENT, CARD_M2_GF_DATE, a2GfBase, 'Gf'));

  const byName={};
  (CARDS_BY_SETREG.get('m2|ASIA')||[]).filter(p=>p.cardSet==='m2' && p.region==='ASIA').forEach(p=>{ byName[p.handle]=p; });
  const finalists=new Set();
  _A2G.forEach(entry=>{
    CARD_DUOS.unshift({handles:entry.duo.slice()});
    entry.duo.forEach(nm=>{
      const p=byName[nm]; if(!p) return;
      finalists.add(nm);
      p._a2Gf=entry; p._attrs=null; p.gfEvent=CARD_A2_GF_EVENT;
      p.realGf={rank:entry.rank, pts:entry.pts, matches:entry.matches, wins:entry.wins,
                avgElims:entry.avgElims, avgPlace:entry.avgPlace};
      p.rating=Math.round(clamp(a2GfBase(entry.rank), 30, 99));
      p.rarity=rarityForRating(p.rating);
    });
  });
  Object.keys(byName).forEach(nm=>{
    if(finalists.has(nm)) return;
    const p=byName[nm];
    p.missedGf=true;
    const base = p._a2Playin ? missedGfPlayinBase(p._a2Playin.rank, _A2P.length)
               : p._a2Lcq   ? missedGfLcqBase(p._a2Lcq.rank, _A2L.length) : p.rating-NO_GF_PENALTY;
    p.rating=Math.round(clamp(base, 30, 99));
    p.rarity=rarityForRating(p.rating);
  });
})();


