const CARD_E2_LCQ1_EVENT="FNCS 2026 Major 2 — Last Chance Qualifier Session 1 (Middle East)";
const CARD_E2_LCQ1_DATE="27 июл 2026";
const _E2L=CARD_E2_LCQ_RAW.map(m1Entry);
const _E2L1=CARD_E2_LCQ1_RAW.map(m1Entry);
const _E2G=CARD_E2_GF_RAW.map(m1Entry);
_S.e2p=mkSorts(_E2P);
_S.e2l=mkSorts(_E2L);
_S.e2l1=mkSorts(_E2L1);
_S.e2g=mkSorts(_E2G);

// Ranked inside its own field, against the band REGION_TOP sets for ME.
const e2PlayinBase = r => REGION_TOP.ME - ((r-1)/Math.max(_E2P.length-1,1))*(REGION_TOP.ME-62);
const e2LcqLen  = () => _E2L.length + _E2L1.length;
const e2LcqBase    = r => 62 - ((r-1)/Math.max(e2LcqLen()-1,1))*14;
const e2Lcq1Base   = r => 62 - ((_E2L.length+r-1)/Math.max(e2LcqLen()-1,1))*14;
const e2GfBase     = r => REGION_TOP.ME - ((r-1)/Math.max(_E2G.length-1,1))*(REGION_TOP.ME-70);

(function buildMajor2ME(){
  const known=new Set();
  const add=(entry, ev, date, base, key)=>{
    // Пара, которую здесь не считают: см. CARD_WRONG_REGION.
    if(cardNotHere('m2', 'ME', entry.duo)) return;
    CARD_DUOS.push({handles:entry.duo.slice()});
    entry.duo.forEach(nm=>{
      if(known.has(nm)) return;
      known.add(nm);
      const rating=Math.round(clamp(base(entry.rank), 30, 99));
      const code = E2_NAT_LIQUI[nm] || E2_NAT_TRN[nm] || E2_LCQ1_NAT[nm] || '';
      const card={
        handle:nm, nat: code ? (CC_RU[code]||null) : null,
        natSource: E2_NAT_LIQUI[nm] ? 'liquipedia' : 'tracker',
        liquiName: E2_LIQUI_NAME[nm] || null,
        region:'ME', event:ev, date:date, placement:entry.rank, note:'',
        tier:'cardmode', cardSet:'m2', rarity:rarityForRating(rating), rating,
        org: E2_ORG[nm] || null,
        real:{rank:entry.rank, pts:entry.pts, matches:entry.matches, wins:entry.wins,
              avgElims:entry.avgElims, avgPlace:entry.avgPlace, stage:key}
      };
      card['_e2'+key]=entry;
      pushCard(card);
    });
  };
  _E2P.forEach(e=>{ if(cardNotHere('m2', 'ME', e.duo)) return;
                    TEAMMATE_GROUPS.push(e.duo.slice()); add(e, CARD_E2_PLAYIN_EVENT, CARD_M2_PLAYIN_DATE, e2PlayinBase, 'Playin'); });
  _E2L.forEach(e=>add(e, CARD_E2_LCQ_EVENT, CARD_M2_LCQ_DATE, e2LcqBase, 'Lcq'));
  _E2L1.forEach(e=>add(e, CARD_E2_LCQ1_EVENT, CARD_E2_LCQ1_DATE, e2Lcq1Base, 'Lcq1'));
  _E2G.forEach(e=>add(e, CARD_E2_GF_EVENT, CARD_M2_GF_DATE, e2GfBase, 'Gf'));

  const byName={};
  (CARDS_BY_SETREG.get('m2|ME')||[]).filter(p=>p.cardSet==='m2' && p.region==='ME').forEach(p=>{ byName[p.handle]=p; });
  const finalists=new Set();
  _E2G.forEach(entry=>{
    if(cardNotHere('m2', 'ME', entry.duo)) return;
    CARD_DUOS.unshift({handles:entry.duo.slice()});
    entry.duo.forEach(nm=>{
      const p=byName[nm]; if(!p) return;
      finalists.add(nm);
      p._e2Gf=entry; p._attrs=null; p.gfEvent=CARD_E2_GF_EVENT;
      p.realGf={rank:entry.rank, pts:entry.pts, matches:entry.matches, wins:entry.wins,
                avgElims:entry.avgElims, avgPlace:entry.avgPlace};
      p.rating=Math.round(clamp(e2GfBase(entry.rank), 30, 99));
      p.rarity=rarityForRating(p.rating);
    });
  });
  Object.keys(byName).forEach(nm=>{
    if(finalists.has(nm)) return;
    const p=byName[nm];
    p.missedGf=true;
    const base = p._e2Playin ? missedGfPlayinBase(p._e2Playin.rank, _E2P.length)
               : p._e2Lcq   ? missedGfLcqBase(p._e2Lcq.rank, _E2L.length) : p.rating-NO_GF_PENALTY;
    p.rating=Math.round(clamp(base, 30, 99));
    p.rarity=rarityForRating(p.rating);
  });
})();


