const CARD_O2_LCQ1_EVENT="FNCS 2026 Major 2 — Last Chance Qualifier Session 1 (Oceania)";
const CARD_O2_LCQ1_DATE="27 июл 2026";
const _O2L=CARD_O2_LCQ_RAW.map(m1Entry);
const _O2L1=CARD_O2_LCQ1_RAW.map(m1Entry);
const _O2G=CARD_O2_GF_RAW.map(m1Entry);
_S.o2p=mkSorts(_O2P);
_S.o2l=mkSorts(_O2L);
_S.o2l1=mkSorts(_O2L1);
_S.o2g=mkSorts(_O2G);

// Ranked inside its own field, against the band REGION_TOP sets for OCE.
const o2PlayinBase = r => REGION_TOP.OCE - ((r-1)/Math.max(_O2P.length-1,1))*(REGION_TOP.OCE-62);
const o2LcqLen  = () => _O2L.length + _O2L1.length;
const o2LcqBase    = r => 62 - ((r-1)/Math.max(o2LcqLen()-1,1))*14;
const o2Lcq1Base   = r => 62 - ((_O2L.length+r-1)/Math.max(o2LcqLen()-1,1))*14;
const o2GfBase     = r => REGION_TOP.OCE - ((r-1)/Math.max(_O2G.length-1,1))*(REGION_TOP.OCE-70);

(function buildMajor2OCE(){
  const known=new Set();
  const add=(entry, ev, date, base, key)=>{
    CARD_DUOS.push({handles:entry.duo.slice()});
    entry.duo.forEach(nm=>{
      if(known.has(nm)) return;
      known.add(nm);
      const rating=Math.round(clamp(base(entry.rank), 30, 99));
      const code = O2_NAT_LIQUI[nm] || O2_NAT_TRN[nm] || O2_LCQ1_NAT[nm] || '';
      const card={
        handle:nm, nat: code ? (CC_RU[code]||null) : null,
        natSource: O2_NAT_LIQUI[nm] ? 'liquipedia' : 'tracker',
        liquiName: O2_LIQUI_NAME[nm] || null,
        region:'OCE', event:ev, date:date, placement:entry.rank, note:'',
        tier:'cardmode', cardSet:'m2', rarity:rarityForRating(rating), rating,
        org: O2_ORG[nm] || null,
        real:{rank:entry.rank, pts:entry.pts, matches:entry.matches, wins:entry.wins,
              avgElims:entry.avgElims, avgPlace:entry.avgPlace, stage:key}
      };
      card['_o2'+key]=entry;
      pushCard(card);
    });
  };
  _O2P.forEach(e=>{ TEAMMATE_GROUPS.push(e.duo.slice()); add(e, CARD_O2_PLAYIN_EVENT, CARD_M2_PLAYIN_DATE, o2PlayinBase, 'Playin'); });
  _O2L.forEach(e=>add(e, CARD_O2_LCQ_EVENT, CARD_M2_LCQ_DATE, o2LcqBase, 'Lcq'));
  _O2L1.forEach(e=>add(e, CARD_O2_LCQ1_EVENT, CARD_O2_LCQ1_DATE, o2Lcq1Base, 'Lcq1'));
  _O2G.forEach(e=>add(e, CARD_O2_GF_EVENT, CARD_M2_GF_DATE, o2GfBase, 'Gf'));

  const byName={};
  (CARDS_BY_SETREG.get('m2|OCE')||[]).filter(p=>p.cardSet==='m2' && p.region==='OCE').forEach(p=>{ byName[p.handle]=p; });
  const finalists=new Set();
  _O2G.forEach(entry=>{
    CARD_DUOS.unshift({handles:entry.duo.slice()});
    entry.duo.forEach(nm=>{
      const p=byName[nm]; if(!p) return;
      finalists.add(nm);
      p._o2Gf=entry; p._attrs=null; p.gfEvent=CARD_O2_GF_EVENT;
      p.realGf={rank:entry.rank, pts:entry.pts, matches:entry.matches, wins:entry.wins,
                avgElims:entry.avgElims, avgPlace:entry.avgPlace};
      p.rating=Math.round(clamp(o2GfBase(entry.rank), 30, 99));
      p.rarity=rarityForRating(p.rating);
    });
  });
  Object.keys(byName).forEach(nm=>{
    if(finalists.has(nm)) return;
    const p=byName[nm];
    p.missedGf=true;
    const base = p._o2Playin ? missedGfPlayinBase(p._o2Playin.rank, _O2P.length)
               : p._o2Lcq   ? missedGfLcqBase(p._o2Lcq.rank, _O2L.length) : p.rating-NO_GF_PENALTY;
    p.rating=Math.round(clamp(base, 30, 99));
    p.rarity=rarityForRating(p.rating);
  });
})();



// ---------- FNCS 2025 Major 1: parsed stages, bands, and one builder ----------
// The fourteen 2026 builders above are ~340 lines each and differ in ten
// values. Copying that seven more times would add roughly 2400 lines of
// duplication for no new behaviour, so 2025 gets one parameterised builder
// called once per region. The 2026 builders are deliberately left alone: they
// are shipped and balanced, and rewriting them onto this function would risk
// moving live ratings inside a commit that is supposed to add a mode.

// Eliminations climb with the stage in 2025 -- 1 in the Last Chance Qualifier,
// 2 in the Play-In, 4 in the Grand Finals. Measured off Epic's own point
// breakdown in all seven regions, so these are readings, not settings.
//
// One table for all three Majors, because the ladder turned out to belong to
// the season rather than to Major 1. Dividing each team's elimination points by
// its eliminations gives a single value per stage across every region of Majors
// 2 and 3 as well -- not an average that lands near 1, 2 and 4, but the only
// quotient that occurs. Three copies of this would be three chances to drift.
