const K2_STAGE_DATE={L:'2–15 мая 2022', P:'20–22 мая 2022', G:'28–29 мая 2022'};
const K3_STAGE_DATE={L:'8–17 июл 2022', P:'22–24 июл 2022', G:'13–14 авг 2022'};
const T_STAGE_DATE={i1:I1_STAGE_DATE, i2:I2_STAGE_DATE, i3:I3_STAGE_DATE, h1:H1_STAGE_DATE, h2:H2_STAGE_DATE, h3:H3_STAGE_DATE, h4:H4_STAGE_DATE, j1:J1_STAGE_DATE, j2:J2_STAGE_DATE, j3:J3_STAGE_DATE, j4:J4_STAGE_DATE, k1:K1_STAGE_DATE, k2:K2_STAGE_DATE, k3:K3_STAGE_DATE, e1:E1_STAGE_DATE, e2:E2_STAGE_DATE, e3:E3_STAGE_DATE, f1:F1_STAGE_DATE, f2:F2_STAGE_DATE, f3:F3_STAGE_DATE, t1:T1_STAGE_DATE, t2:T2_STAGE_DATE, t3:T3_STAGE_DATE};

const _T={}, _ST={};
T_SETS.forEach(set=>{
  _T[set]={}; _ST[set]={};
  T1_REGIONS.forEach(reg=>{
    if(!T_RAW[set][reg]) return;   // 2024: без NA West
    _T[set][reg]={};
    ['P','L','G'].forEach(st=>{
      _T[set][reg][st]=T_RAW[set][reg][st].map(r=>rowEntry(r, {killMult:(T_KILL_BY_SET[set]||T1_KILL)[st], elimPtsAt:6}));
    });
    // Every stage is ranked against itself, so a card says "this good among the
    // people who were in that lobby" -- same rule the 2026 sets use.
    _ST[set][reg]={P:mkSorts(_T[set][reg].P), L:mkSorts(_T[set][reg].L), G:mkSorts(_T[set][reg].G)};
  });
});

// Same bands as 2026: the Play-In and Grand Finals ceilings come from
// REGION_TOP so the thin regions are compressed rather than clipped, and the
// Last Chance band sits below every ceiling so it needs no compression.
function tBase(set, reg, st, rank){
  const field=_T[set][reg][st].length;
  const ramp=(rank-1)/Math.max(field-1,1);
  if(st==='L') return 62 - ramp*14;
  const top=REGION_TOP[reg]||85;
  return top - ramp*(top - (st==='G' ? 70 : 62));
}

// One pool per Major. Nothing reads these yet -- currentDuos() below has no
// callers, and real-teammate synergy runs off TEAMMATE_GROUPS instead -- but a
// single shared array would be wrong the moment something does, so they are
// kept apart rather than merged.
const CARD_TRIOS_BY_SET={i1:[], i2:[], i3:[], h1:[], h2:[], h3:[], h4:[], j1:[], j2:[], j3:[], j4:[], k1:[], k2:[], k3:[], e1:[], e2:[], e3:[], f1:[], f2:[], f3:[], t1:[], t2:[], t3:[]};
function buildCardSetRegion(cfg){
  /* Один человек — одно написание на весь набор. Строки этапов собраны с разных страниц,
     и финал World Cup Duos писал «nyhrox»/«aqua», а квалы — «Nyhrox»/«Aqua»: чемпионы мира
     не находили своей строки финала и читались «не дошли до финала». Ник берётся из первого
     этапа, где он встретился (P, потом L, потом G). */
  /* Пробел по краям чистится и в составе: pushCard режет его у ника карточки (7bc4865), а строка
     состава оставалась «Dela » — 11 трио 2025-го теряли своего и выпадали из реалистичной симуляции,
     финалисты с таким ником не находили карточку (полный прогон 9.10, check-realistic: 165 вместо 176).
     Флаг ищется по исходному написанию (rawNick), в T_NAT он записан с пробелом. */
  const canon=new Map(), rawNick=new Map();
  ['P','L','G'].forEach(st=>(cfg.stages[st]||[]).forEach(e=>{
    e.duo=e.duo.map(raw=>{ const nm=String(raw).trim(); if(nm!==raw && !rawNick.has(nm)) rawNick.set(nm, raw); const k=nm.toLowerCase(); if(!canon.has(k)) canon.set(k, nm); return canon.get(k); });
  }));
  const known=new Set();
  const trios=CARD_TRIOS_BY_SET[cfg.set];
  const stageDate=T_STAGE_DATE[cfg.set];
  const stageEvent=st=>T_EVENT_NAME[cfg.set]+' — '+(T_STAGE_NAME_BY_SET[cfg.set]||T1_STAGE_NAME)[st]+' ('+T1_REGION_NAME[cfg.region]+')';
  const add=(entry, st)=>{
    // Пара, которую здесь не считают: см. CARD_WRONG_REGION.
    if(cardNotHere(cfg.set, cfg.region, entry.duo)) return;
    trios.push({handles:entry.duo.slice()});
    entry.duo.forEach(nm=>{
      if(known.has(nm)) return;
      known.add(nm);
      const rating=Math.round(clamp(cfg.base(st, entry.rank), 30, 99));
      const code=cfg.nat[nm]||cfg.nat[rawNick.get(nm)]||'';
      const card={
        handle:nm, nat: code ? (CC_RU[code]||null) : null,
        natSource:'tracker',
        region:cfg.region, event:stageEvent(st), date:stageDate[st],
        placement:entry.rank, note:'',
        tier:'cardmode', cardSet:cfg.set, rarity:rarityForRating(rating), rating,
        org:null,
        real:{rank:entry.rank, pts:entry.pts, matches:entry.matches, wins:entry.wins,
              avgElims:entry.avgElims, avgPlace:entry.avgPlace, stage:st}
      };
      // One descriptor per card instead of one branch per region-stage in the
      // attribute dispatch, which is already a chain of forty-odd.
      card._t1={entry:entry, sorts:cfg.sorts[st]};
      card._t1Stage=st;
      pushCard(card);
    });
  };
  cfg.stages.P.forEach(e=>{ TEAMMATE_GROUPS.push(e.duo.slice()); add(e,'P'); });
  cfg.stages.L.forEach(e=>add(e,'L'));
  cfg.stages.G.forEach(e=>add(e,'G'));

  // Finalists are rebuilt from the Grand Finals; everyone else keeps their
  // qualifying rating minus the miss penalty. Same rule as m1 and m2.
  const byName={};
  (CARDS_BY_SETREG.get(cfg.set+'|'+cfg.region)||[]).filter(p=>p.cardSet===cfg.set && p.region===cfg.region)
              .forEach(p=>{ byName[p.handle]=p; });
  const finalists=new Set();
  cfg.stages.G.forEach(entry=>{
    trios.unshift({handles:entry.duo.slice()});
    entry.duo.forEach(nm=>{
      const p=byName[nm]; if(!p) return;
      finalists.add(nm);
      p._t1={entry:entry, sorts:cfg.sorts.G};
      p._t1Stage='G'; p._attrs=null; p.gfEvent=stageEvent('G');
      p.realGf={rank:entry.rank, pts:entry.pts, matches:entry.matches, wins:entry.wins,
                avgElims:entry.avgElims, avgPlace:entry.avgPlace};
      p.rating=Math.round(clamp(cfg.base('G', entry.rank), 30, 99));
      p.rarity=rarityForRating(p.rating);
    });
  });
  Object.keys(byName).forEach(nm=>{
    if(finalists.has(nm)) return;
    const p=byName[nm];
    p.missedGf=true;
    const base = p._t1Stage==='P' ? missedGfPlayinBase(p._t1.entry.rank, cfg.stages.P.length)
               : p._t1Stage==='L' ? missedGfLcqBase(p._t1.entry.rank, cfg.stages.L.length)
               : p.rating-NO_GF_PENALTY;
    p.rating=Math.round(clamp(base, 30, 99));
    p.rarity=rarityForRating(p.rating);
    p._attrs=null;
  });
}

// Seven regions times three Majors, through the one builder. The order matters
// only in that a set must be built before the ledger pass below can rate it.
T_SETS.forEach(set=>{
  T1_REGIONS.forEach(reg=>{
    if(!_T[set][reg]) return;
    buildCardSetRegion({
      set:set, region:reg, nat:T_NAT[set],
      stages:_T[set][reg], sorts:_ST[set][reg],
      base:(st, rank)=>tBase(set, reg, st, rank)
    });
  });
});


