const _DIV={}, _DVS={};
DIV_WEEKS.forEach(w=>{ _DIV[w]=DIV_RAW[w].map(m1Entry); _DVS[w]=mkSorts(_DIV[w]); });
/* Полоса финала недели — целиком под полосой гранд-финала Мейджора и ЛАНа.
 *
 * Правило: «див капы меньше должны давать, чем финалы мажора и
 * финалы ланов». Сверху и в середине так и было — 90 против 96 у Мейджора, 82
 * против 83 на половине поля, — а внизу переворачивалось: пол финала недели
 * стоял на 74, пол гранд-финала на 70, и последний в кубке дивизиона читался
 * выше последнего в гранд-финале.
 *
 * Двинут только пол, 74 → 68. Этого достаточно, чтобы кривая лежала ниже во
 * всех точках: на любой доле поля 90−d·22 меньше, чем 96−d·26. Верх не тронут —
 * он и так ниже, а опускать победителя недели ещё сильнее значило бы сказать,
 * что выиграть комнату дивизиона почти ничего не стоит. */
const DIV_BAND=[90, 68];
function divBase(week, rank){
  const n=(_DIV[week]||[]).length;
  const ramp=Math.min(1, Math.max(0, (rank-1)/Math.max(n-1, 1)));
  return DIV_BAND[0]-ramp*(DIV_BAND[0]-DIV_BAND[1]);
}
const DIV_EVENT=w=>'FNCS 2026 Division 1 — Week '+w+' Finals (Europe)';
/* Клуб человек носит, а не событие. У остальных наборов есть своя карта
   организаций, у Tracker в этой выгрузке её нет — только ник с приставкой,
   разбирать которую значило бы угадывать. Поэтому клуб берётся с карточки,
   которая у человека уже есть: наборы строятся раньше, и к этому месту они
   собраны. Без этого careerRosterNowEU, который держит самую свежую карточку,
   отдавал бы финал недели без клуба — и клуб пропадал из списка у всех, чьё
   последнее событие это он. Поймал check-career-roster-club. */
function divOrgOf(){
  const m=new Map();
  PLAYERS_BASE.forEach(c=>{ if(c.org && !m.has(hKey(c))) m.set(hKey(c), c.org); });
  return m;
}
function buildDivWeek(w, orgs){
  const set='d'+w, ev=DIV_EVENT(w), date=DIV_DATE[w]||'';
  (_DIV[w]||[]).forEach(entry=>{
    TEAMMATE_GROUPS.push(entry.duo.slice());
    entry.duo.forEach(nm=>{
      const rating=Math.round(clamp(divBase(w, entry.rank), 30, 99));
      // Tracker пишет код страны заглавными; CC_RU ключуется так, как страны
      // записаны в остальном файле.
      const code=(DIV_NAT[nm]||'').toLowerCase();
      const card={handle:nm, nat: code ? (CC_RU[code]||null) : null,
                  natSource:'tracker', region:'EU', event:ev, date:date,
                  placement:entry.rank, note:'', tier:'cardmode', cardSet:set,
                  org:(orgs.get(hKey({handle:nm}))||null),
                  rarity:rarityForRating(rating), rating,
                  real:{rank:entry.rank, pts:entry.pts, matches:entry.matches,
                        wins:entry.wins, avgElims:entry.avgElims,
                        avgPlace:entry.avgPlace, stage:'Final'}};
      card['_'+set+'Final']=entry;
      card._dv={entry:entry, sorts:_DVS[w], week:w};
      pushCard(card);
    });
  });
}
(function(){ const orgs=divOrgOf(); DIV_WEEKS.forEach(w=>buildDivWeek(w, orgs)); })();
