// whichever years the player left selected in the era filter.
// Which island's loot is in play: the Major's own in card mode, and in the free
// modes whichever island the player picked on the mode screen.
/* Набор без своего острова играет на острове своего сезона (его слово 29.09: «оружие у драфта со своего
   сезона должно быть»): World Cup Duos 2019 (h2) — Season 9, как World Cup Solo (h1). Без этого h2
   падал на остров и лут 2026-го. */
const SET_ISLAND={h2:'h1'};
// Остров этапа поверх острова набора карточек: Лион играется на C6S4, хотя карточки — Мейджора 3 (t3). См. runGlobalChampionship2025.
var LOOT_ISLAND_NOW=null;
function activeIslandSet(){
  if(LOOT_ISLAND_NOW) return LOOT_ISLAND_NOW;
  const k=CARD_MODE ? CARD_SET : (typeof pendingMapSet==='undefined' ? null : pendingMapSet);
  return (k && SET_ISLAND[k]) || k;
}
function activeWeaponPool(){
  if(T_WEAPON_POOLS[activeIslandSet()]) return T_WEAPON_POOLS[activeIslandSet()];
  if(CARD_MODE && T_WEAPON_POOLS[CARD_SET]) return T_WEAPON_POOLS[CARD_SET];
  if(CARD_MODE && CARD_SET==='m1') return M1_WEAPON_POOL;
  if(CARD_MODE) return WEAPON_POOL;
  const years=(preSelectedYears||[]).filter(y=>SEASON_WEAPON_POOLS[y]);
  if(!years.length) return WEAPON_POOL;
  const out=[];
  years.forEach(y=>out.push(...SEASON_WEAPON_POOLS[y]));
  return out.length ? out : WEAPON_POOL;
}

function lootPoolSeasonName(){
  const pick=y=>{ const s=SEASON_LOOT[y]; return s ? (LANG==='ru'?s.ru:s.en) : null; };
  if(T_SEASON_NAME[activeIslandSet()]) return T_SEASON_NAME[activeIslandSet()][LANG==='ru' ? 0 : 1];
  if(CARD_MODE && CARD_SET==='m1') return LANG==='ru' ? 'Глава 7, сезон 2' : 'Chapter 7, Season 2';
  const years=(preSelectedYears||[]).filter(y=>SEASON_LOOT[y]).sort((a,b)=>a-b);
  if(!years.length) return pick(2026);
  return years.map(pick).filter((v,i,a)=>a.indexOf(v)===i).join(' + ');
}

function updateLootPoolNote(){
  const el=document.getElementById('lootPoolNote');
  if(el) el.textContent=L().lootPoolNote(lootPoolSeasonName());
}

let squadSize=4, drafted=[], pool=[], activeRegion='ALL', round=0;
let draftedWeapons=[], draftedHeals=[], currentWeaponOptions=[], currentHealOptions=[];
let roundPlayerPicked=false, roundWeaponPicked=false, roundHealPicked=false;

// Part of the loot comes in tiers that share a name and a silhouette. A Fishing
// Rod next to a Pro Fishing Rod, or a Shield Potion next to a Small Shield
// Potion, reads as the pack repeating itself even though they are two different
// items — so a pack offers at most one member of each family.
const LOOT_FAMILY={
  "Fishing Rod":"fishing rod",       "Pro Fishing Rod":"fishing rod",
  "Shield Potion":"shield potion",   "Small Shield Potion":"shield potion",
  "Chug Jug":"chug",                 "Chug Splash":"chug",
  "Flopper":"flopper",               "Midas Flopper":"flopper",
  "Vault Key":"vault key",           "Epic Vault Keycard":"vault key"
};
const packKey=w=>LOOT_FAMILY[w.name]||w.name;

// A pack offers four different items: the same card twice in one row reads as a
// bug, and it quietly halves the choice. Keyed by name rather than by object,
// because a multi-season weapon pool carries the same gun once per season it
// appeared in, and each season expands it into one entry per rarity.
function samplePack(src, n){
  const bag=src.slice(), seen=new Set(), out=[];
  while(out.length<n && bag.length){
    const w=bag.splice(Math.floor(Math.random()*bag.length),1)[0];
    const key=packKey(w);
    if(seen.has(key)) continue;
    seen.add(key);
    out.push(w);
  }
  // A single-season pool can hold fewer than n distinct names; top up with repeats.
  while(out.length<n && src.length) out.push(src[Math.floor(Math.random()*src.length)]);
  return out;
}

function generateWeaponPack(){
  return samplePack(activeWeaponPool(), 4)
    .map(w=>({name:w.name, rarity:w.rarity, icon:w.icon, mod:w.mod, color:RARITY_COLOR[w.rarity]}));
}

function generateHealPack(){
  const src = T_CONSUMABLE_POOLS[activeIslandSet()] ? T_CONSUMABLE_POOLS[activeIslandSet()]
            : (CARD_MODE && CARD_SET==='m1') ? M1_CONSUMABLE_POOL : M2_CONSUMABLE_POOL;
  return samplePack(src, 4)
    .map(w=>({name:w.name, rarity:w.rarity, icon:w.icon, mod:w.mod, color:CONSUMABLE_RARITY_COLOR[w.rarity]}));
}


